using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Diagnostics;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;using KianaPet;
class SkinShowcaseTests {
 static int checks;static List<string> names=new List<string>();static List<object> samples=new List<object>();
 static object F(object o,string key){return o.GetType().GetField(key,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}
 static void Set(object o,string key,object value){o.GetType().GetField(key,BindingFlags.NonPublic|BindingFlags.Instance).SetValue(o,value);}
 static object Call(object o,string key,params object[] args){return o.GetType().GetMethod(key,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,args);}
 static void Check(bool value,string message){if(!value)throw new Exception(message);checks++;names.Add(message);}
 static string Text(PetWindow pet){return ((TextBlock)F(pet,"bubbleText")).Text;}
 static void Clear(PetWindow pet){((Border)F(pet,"bubble")).Visibility=Visibility.Hidden;Set(pet,"bubbleUntil",0d);}
 static bool Running(PetWindow pet){return (bool)F(pet,"skinShowcaseRunning");}
 static void Snapshot(PetWindow pet,int index){pet.UpdateLayout();var content=(FrameworkElement)pet.Content;var visual=new DrawingVisual();using(var dc=visual.RenderOpen()){dc.DrawRectangle(new SolidColorBrush(Color.FromRgb(248,246,252)),null,new Rect(0,0,240,360));dc.DrawRectangle(new VisualBrush(content){Stretch=Stretch.Fill},null,new Rect((240-pet.Width)/2,(360-pet.Height)/2,pet.Width,pet.Height));}var bitmap=new RenderTargetBitmap(360,540,144,144,PixelFormats.Pbgra32);bitmap.Render(visual);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(Path.Combine(Store.Root,"frame-"+index.ToString("000")+".png")))encoder.Save(file);}
 [STAThread]static int Main(string[] args){Store.Root=args[0];Directory.CreateDirectory(Store.Root);var deck=new SkinChangeMessages(new Random(417));string last=null;for(int round=0;round<100;round++){var seen=new HashSet<string>();for(int i=0;i<8;i++){string line=deck.Next();if(line==last||!seen.Add(line)||!SkinChangeMessages.Contains(line))throw new Exception("message deck repeats or contains invalid text");last=line;}}Check(true,"100 shuffled rounds are unique and never repeat across a boundary");
  Store.Save(new Config{LinkChatGPT=false,MusicEnabled=false,Walking=false,Gravity=false,AmbientActions=false,SleepSchedule=false,IdleSleep=false,HideFullscreen=false,LaunchChatGPTOnStart=false,LaunchMusicOnStart=false,NoticeSound=false,SkinShuffleEnabled=false,SkinShuffleOnStart=false,SmoothTransitions=true,ReduceMotion=false,Bubbles=true});var app=new Application{ShutdownMode=ShutdownMode.OnLastWindowClose};var pet=new PetWindow(true);bool passed=false;
  pet.Loaded+=async delegate{try{
   await Task.Delay(1100);((DispatcherTimer)F(pet,"animation")).Stop();foreach(var w in app.Windows.OfType<SettingsWindow>().ToArray())w.Close();Set(pet,"hover",false);Set(pet,"interaction",null);Set(pet,"menuLayerYielding",false);Set(pet,"displayPending",false);Set(pet,"sleeping",false);Set(pet,"state","idle");Clear(pet);
   double now=((Stopwatch)F(pet,"clock")).Elapsed.TotalSeconds;Set(pet,"stateAt",now-20);double phase=(double)F(pet,"stateAt"),width=pet.Width,height=pet.Height;var poll=((DispatcherTimer)F(pet,"poll")).Interval;var musicPoll=((DispatcherTimer)F(pet,"musicTimer")).Interval;
   var turn=(RotateTransform)F(pet,"skinShowcaseTurn");var lift=(TranslateTransform)F(pet,"skinShowcaseLift");var sprite=(Image)F(pet,"sprite");
   string id=SkinShuffleRules.Defaults.First(s=>s!=pet.Settings.Skin);Check((bool)Call(pet,"ApplyAutomaticSkin",id,now),"safe automatic swap succeeds");
   if(MotionSettings.Enabled){Check(!Running(pet),"showcase waits for the fade to finish");bool left=false,right=false,up=false;var clock=Stopwatch.StartNew();int index=0;while(clock.ElapsedMilliseconds<1350){await Task.Delay(40);left|=turn.Angle<-.5;right|=turn.Angle>.5;up|=lift.Y<-3;samples.Add(new{milliseconds=clock.ElapsedMilliseconds,angle=turn.Angle,lift=lift.Y,showcase=Running(pet)});Snapshot(pet,index++);}Check(left&&right&&up,"rendered standing showcase sways both ways and lifts visibly");Check(!Running(pet)&&turn.Angle==0&&lift.Y==0,"completion restores neutral transforms");}
   Check(SkinChangeMessages.Contains(Text(pet)),"automatic completion uses the randomized deck");Check((double)F(pet,"stateAt")==phase&&F(pet,"interaction")==null&&pet.Width==width&&pet.Height==height&&((DispatcherTimer)F(pet,"poll")).Interval==poll&&((DispatcherTimer)F(pet,"musicTimer")).Interval==musicPoll,"cosmetic showcase preserves action phase, input state, bounds and provider polling");
   if(MotionSettings.Enabled){
    Set(pet,"state","music-quiet");Set(pet,"drawnMusicState","music-quiet");pet.Settings.MusicEnabled=true;pet.Music.Current=new MusicState{Connected=true,Playing=true,Title="Synthetic song",Id="123",HasPosition=false};Call(pet,"ChooseMusicReaction",now-10,true);Call(pet,"ChooseMusicReaction",now,true);Call(pet,"DrawAnimation",20000d);var planner=F(pet,"musicReactionPlanner");var entered=F(planner,"enteredAt");var spriteTransform=sprite.RenderTransform;Clear(pet);Call(pet,"ShowSkinShuffleFeedback");await Task.Delay(220);Check(Running(pet)&&Math.Abs(turn.Angle)<=3.6&&lift.Y>=-1.6&&lift.Y<0,"seated showcase uses a smaller sway and lift");Check(ReferenceEquals(spriteTransform,sprite.RenderTransform)&&ReferenceEquals(planner,F(pet,"musicReactionPlanner"))&&Equals(entered,F(planner,"enteredAt"))&&(double)F(pet,"stateAt")==phase,"seated music transform and planner timeline remain intact");
    Call(pet,"SkinVisualActionChanged","running");Check(!Running(pet)&&turn.Angle==0&&lift.Y==0,"new action cancels the showcase immediately");Set(pet,"state","idle");
    foreach(string flag in new[]{"pressed","dragging","quietActive","sessionLocked","manualHidden","fullscreenHidden","displayPending"}){Clear(pet);Call(pet,"ShowSkinShuffleFeedback");Check(Running(pet),"showcase begins before "+flag);Set(pet,flag,true);Call(pet,"MaintainSkinVisual");Check(!Running(pet)&&turn.Angle==0&&lift.Y==0,"showcase yields to "+flag);Set(pet,flag,false);}
    Clear(pet);Call(pet,"ShowSkinShuffleFeedback");pet.Settings.LinkChatGPT=true;pet.Link.Current.Connected=true;pet.Link.Current.State="running";pet.Link.Current.At=DateTime.UtcNow;Call(pet,"MaintainSkinVisual");Check(!Running(pet),"incoming GPT work cancels the showcase");pet.Settings.LinkChatGPT=false;
    Clear(pet);pet.Settings.Bubbles=false;Call(pet,"ShowSkinShuffleFeedback");Check(Running(pet)&&((Border)F(pet,"bubble")).Visibility!=Visibility.Visible,"showcase works with bubbles disabled");pet.Settings.Bubbles=true;Call(pet,"StopSkinVisual");
    pet.Say("任务已完成",5);double bubbleUntil=(double)F(pet,"bubbleUntil");Call(pet,"ShowSkinShuffleFeedback");Check(Text(pet)=="任务已完成"&&(double)F(pet,"bubbleUntil")==bubbleUntil,"existing task message retains its text and expiry");Call(pet,"StopSkinVisual");
    Clear(pet);Call(pet,"PlaySkinShowcase");await Task.Delay(50);int token=(int)F(pet,"skinShowcaseToken");Call(pet,"PlaySkinShowcase");await Task.Delay(850);Check(Running(pet)&&(int)F(pet,"skinShowcaseToken")>token,"old completion cannot stop a newer showcase");await Task.Delay(130);Check(!Running(pet)&&turn.Angle==0&&lift.Y==0,"new showcase finishes without stale transforms");
    Clear(pet);Call(pet,"PlaySkinShowcase");pet.Hide();Check(!Running(pet)&&turn.Angle==0,"hidden pet releases cosmetic motion");pet.Show();
    Call(pet,"PlaySkinShowcase");pet.ResizePet();Check(!Running(pet)&&lift.Y==0,"resize releases cosmetic motion");
   }
   pet.Settings.ReduceMotion=true;Call(pet,"ApplyInputOptions");Clear(pet);Call(pet,"ShowSkinShuffleFeedback");Check(!Running(pet)&&SkinChangeMessages.Contains(Text(pet)),"reduced motion keeps randomized static feedback");pet.Settings.ReduceMotion=false;pet.Settings.SmoothTransitions=false;Call(pet,"ApplyInputOptions");Clear(pet);Call(pet,"ShowSkinShuffleFeedback");Check(!Running(pet)&&turn.Angle==0&&lift.Y==0,"disabled smooth transitions keep the body still");
   pet.Settings.SmoothTransitions=true;Call(pet,"ApplyInputOptions");Set(pet,"interaction",null);Clear(pet);pet.SelectSkin(SkinShuffleRules.Defaults.First(s=>s!=pet.Settings.Skin));string manual=Text(pet);Check(Equals(F(pet,"interaction"),"waving")&&SkinChangeMessages.Contains(manual),"manual selection keeps waving with varied text");await Task.Delay(370);Check(!Running(pet)&&Text(pet)==manual,"manual wave is not stacked with a second showcase or message");Set(pet,"interaction",null);Call(pet,"PlaySkinShowcase");passed=true;
  }catch(Exception e){Store.Atomic("error.json",new{error=e.ToString(),checks});}finally{foreach(var w in app.Windows.Cast<Window>().Where(w=>w!=pet).ToArray())w.Close();pet.Close();}};app.Run(pet);try{Check(!Running(pet)&&((RotateTransform)F(pet,"skinShowcaseTurn")).Angle==0&&((TranslateTransform)F(pet,"skinShowcaseLift")).Y==0,"closing clears all showcase clocks");}catch(Exception e){passed=false;Store.Atomic("error.json",new{error=e.ToString(),checks});}Store.Atomic("result.json",new{passed,checks,names,samples});return passed?0:1;
 }
}
